insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:soupe thai', 'Thai soup', array['en:thai soup', 'en:tom kha kai', 'en:tom yum', 'en:thai coconut soup', 'en:coconut lemongras soup']::text[], 'dish', $r$[{"title":"Thai chicken and coconut soup","intro":"Tom kha kai: chicken in a coconut broth with lemongrass and lime.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"tom kha gai","veg":false,"oven":false,"cold":false,"missing":"","origin":"Thai recipe","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":1,"unit":"","have":false},{"name":"lemongrass","plural":"lemongrass","qty":2,"unit":"","have":false},{"name":"fresh ginger","plural":"fresh ginger","qty":1,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":150,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"fish sauce","plural":"fish sauce","qty":2,"unit":"tbsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Bring 50 cl of water to a simmer with the stock cube, bruised lemongrass and sliced ginger.","timer":{"label":"Cooking","min":10}},{"text":"Add the coconut milk and the chicken in thin strips, and cook for 8 min.","timer":{"label":"Cooking","min":8}},{"text":"Add the sliced mushrooms and cook for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Off the heat, add the lime juice and fish sauce.","timer":null},{"text":"Sprinkle with coriander.","timer":null}],"variant":"The classic","change":""},{"title":"Thai prawn soup","intro":"A hot and sour Thai soup with prawns.","minutes":25,"calories":220,"difficulty":"Facile","imageSearch":"tom yum shrimp","veg":false,"oven":false,"cold":false,"missing":"","origin":"Thai recipe","serves":4,"items":[{"name":"peeled prawn","plural":"peeled prawns","qty":300,"unit":"g","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":1,"unit":"","have":false},{"name":"lemongrass","plural":"lemongrass","qty":2,"unit":"","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":150,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":150,"unit":"g","have":false},{"name":"chilli","plural":"chillies","qty":1,"unit":"","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"fish sauce","plural":"fish sauce","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Bring 1 litre of water to a simmer with the stock cube, lemongrass and chilli.","timer":{"label":"Cooking","min":10}},{"text":"Add the mushrooms and tomatoes, and cook for 3 min.","timer":null},{"text":"Add the prawns and cook for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Off the heat, add the lime juice and fish sauce.","timer":null}],"variant":"Prawns","change":"Tom yum: a spicy broth with prawns."},{"title":"Vegetarian Thai soup","intro":"A coconut and lemongrass soup with tofu.","minutes":25,"calories":300,"difficulty":"Facile","imageSearch":"vegetarian thai coconut soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"firm tofu","plural":"firm tofu","qty":200,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"lemongrass","plural":"lemongrass","qty":2,"unit":"","have":false},{"name":"fresh ginger","plural":"fresh ginger","qty":1,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":150,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Bring 50 cl of water to a simmer with the stock cube, lemongrass and ginger.","timer":{"label":"Cooking","min":10}},{"text":"Add the coconut milk, diced tofu and mushrooms.","timer":null},{"text":"Cook for 8 min.","timer":{"label":"Cooking","min":8}},{"text":"Add the lime juice and soy sauce.","timer":null}],"variant":"Vegetarian","change":"With tofu and vegetables."}]$r$::jsonb, 'claude')
