insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:blini', 'Blinis', array['en:homemade blini', 'en:salmon blini']::text[], 'dish', $r$[{"title":"Homemade blinis","intro":"Small, thick, fluffy pancakes to top with cream and smoked salmon.","minutes":40,"calories":180,"difficulty":"Facile","imageSearch":"blinis smoked salmon","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"melted butter","plural":"melted butter","qty":20,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"smoked salmon","plural":"smoked salmon","qty":4,"unit":"slices","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the flour, baking powder, egg yolks, milk and melted butter.","timer":null},{"text":"Whisk the whites until stiff and fold them in.","timer":null},{"text":"Cook small rounds of batter for 1 min on each side in a buttered pan.","timer":{"label":"Pan","min":2}},{"text":"Top each blini with crème fraîche, salmon and dill.","timer":null}],"makes":{"n":24,"one":"blini","many":"blinis"},"variant":"The classic","change":""},{"title":"Goat's cheese blinis","intro":"Party blinis with fresh goat's cheese.","minutes":35,"calories":170,"difficulty":"Facile","imageSearch":"blinis goat cheese","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"fresh goat's cheese","plural":"fresh goat's cheeses","qty":150,"unit":"g","have":false},{"name":"chives","plural":"chives","qty":null,"unit":"","have":false}],"steps":[{"text":"Make the blini batter and cook the blinis.","timer":{"label":"Pan","min":2}},{"text":"Mix the fresh goat's cheese with the chopped chives.","timer":null},{"text":"Top each blini.","timer":null},{"text":"Season with pepper and serve.","timer":null}],"makes":{"n":24,"one":"blini","many":"blinis"},"variant":"Vegetarian","change":"Topped with a herby goat's cheese cream."},{"title":"Buckwheat blinis","intro":"Buckwheat blinis, with a more rustic flavour.","minutes":90,"calories":170,"difficulty":"Moyen","imageSearch":"buckwheat blinis","veg":false,"oven":false,"cold":false,"missing":"","origin":"Russian inspired","serves":4,"items":[{"name":"buckwheat flour","plural":"buckwheat flour","qty":100,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":50,"unit":"g","have":false},{"name":"fresh yeast","plural":"fresh yeast","qty":5,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":25,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"smoked salmon","plural":"smoked salmon","qty":4,"unit":"slices","have":false}],"steps":[{"text":"Dissolve the yeast in the lukewarm milk, then add the flours and egg yolks.","timer":null},{"text":"Leave to rise for 1 h.","timer":{"label":"Rising","min":60}},{"text":"Fold in the whisked egg whites.","timer":null},{"text":"Cook the blinis for 1 min on each side and top with crème fraîche and salmon.","timer":{"label":"Pan","min":2}}],"makes":{"n":24,"one":"blini","many":"blinis"},"variant":"Buckwheat","change":"With buckwheat flour, Russian-style."}]$r$::jsonb, 'claude')
