insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pain d epice', 'Pain d''épices', array['en:french spice bread', 'en:honey spice cake', 'en:gingerbread loaf']::text[], 'dish', $r$[{"title":"Pain d'épices","intro":"Soft honey spice bread flavoured with cinnamon, ginger and aniseed.","minutes":80,"calories":280,"difficulty":"Facile","imageSearch":"french gingerbread loaf","veg":true,"oven":true,"cold":false,"missing":"","origin":"Dijon speciality","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":250,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":15,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"brown sugar","plural":"brown sugar","qty":60,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"mixed spice","plural":"mixed spice","qty":2,"unit":"tsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 160 °C.","timer":null},{"text":"Heat the milk with the honey and sugar, without letting it boil.","timer":null},{"text":"Mix the flour, baking powder and spices, then add the honey milk and the egg.","timer":null},{"text":"Pour into a buttered loaf tin and bake for 1 h.","timer":{"label":"Oven","min":60}},{"text":"Wrap and leave for a day: it is even better.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Orange pain d'épices","intro":"A Christmas spice bread flavoured with orange.","minutes":80,"calories":290,"difficulty":"Facile","imageSearch":"orange gingerbread","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":250,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":15,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"mixed spice","plural":"mixed spice","qty":2,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 160 °C.","timer":null},{"text":"Heat the milk with the honey and the orange zest.","timer":null},{"text":"Mix the flour, baking powder and spices, then add the milk, egg and orange juice.","timer":null},{"text":"Pour into a tin and bake for 1 h.","timer":{"label":"Oven","min":60}}],"dessert":true,"variant":"Orange","change":"With orange zest and peel."},{"title":"Old-fashioned pain d'épices","intro":"The old-fashioned egg-free spice bread.","minutes":75,"calories":270,"difficulty":"Facile","imageSearch":"eggless gingerbread loaf","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rye flour","plural":"rye flour","qty":250,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":250,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"bicarbonate of soda","plural":"bicarbonate of soda","qty":1,"unit":"tsp","have":false},{"name":"mixed spice","plural":"mixed spice","qty":2,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 160 °C.","timer":null},{"text":"Heat the milk with the honey.","timer":null},{"text":"Mix the flour, bicarbonate of soda and spices, then add the honey milk.","timer":null},{"text":"Pour into a tin and bake for 1 h.","timer":{"label":"Oven","min":60}}],"dessert":true,"variant":"Egg-free","change":"Egg-free, with just honey and milk."}]$r$::jsonb, 'claude')
