insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:tarte au chocolat', 'Chocolate tart', array['en:chocolate tart', 'en:chocolate ganache tart', 'en:dark chocolate tart']::text[], 'dish', $r$[{"title":"Chocolate tart","intro":"A sweet shortcrust base with a rich dark chocolate ganache.","minutes":50,"calories":450,"difficulty":"Moyen","imageSearch":"chocolate tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sweet shortcrust pastry","plural":"sweet shortcrust pastries","qty":1,"unit":"","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Blind bake the pastry for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Heat the cream and pour it over the chopped chocolate.","timer":null},{"text":"Stir, then add the butter and the beaten egg.","timer":null},{"text":"Pour into the pastry case and bake for 10 min at 150 °C.","timer":{"label":"Oven","min":10}},{"text":"Leave to cool for at least 1 h.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Chocolate caramel tart","intro":"A chocolate tart with a caramel centre.","minutes":60,"calories":520,"difficulty":"Moyen","imageSearch":"chocolate caramel tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sweet shortcrust pastry","plural":"sweet shortcrust pastries","qty":1,"unit":"","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":30,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"salted butter","plural":"salted butter","qty":40,"unit":"g","have":false}],"steps":[{"text":"Blind bake the pastry for 20 min at 180 °C.","timer":{"label":"Oven","min":20}},{"text":"Make a caramel with the sugar, add 10 cl of hot cream and the butter. Pour it into the pastry case.","timer":null},{"text":"Heat the rest of the cream and melt the chocolate in it.","timer":null},{"text":"Pour the ganache over the caramel and leave to set for 2 h in the fridge.","timer":null}],"dessert":true,"variant":"Caramel","change":"With a layer of salted butter caramel."},{"title":"No-bake chocolate tart","intro":"A quick chocolate tart, no oven needed.","minutes":25,"calories":480,"difficulty":"Facile","imageSearch":"no bake chocolate tart","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"digestive biscuit","plural":"digestive biscuits","qty":200,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Crush the biscuits, mix with the melted butter and press into a tin.","timer":null},{"text":"Heat the cream and pour it over the chocolate.","timer":null},{"text":"Stir and pour over the base.","timer":null},{"text":"Leave to set for 2 h in the fridge.","timer":null}],"dessert":true,"variant":"No-bake","change":"A biscuit base and a ganache."}]$r$::jsonb, 'claude')
