insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:buche de noel', 'Yule log', array['en:yule log', 'en:chocolate yule log', 'en:christma log', 'en:swis roll cake']::text[], 'dish', $r$[{"title":"Chocolate yule log","intro":"A rolled sponge filled and covered with chocolate ganache, for Christmas dinner.","minutes":70,"calories":420,"difficulty":"Difficile","imageSearch":"chocolate yule log","veg":true,"oven":true,"cold":false,"missing":"","origin":"Christmas tradition","serves":4,"items":[{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":250,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":40,"unit":"cl","have":false},{"name":"icing sugar","plural":"icing sugar","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Whisk the eggs and sugar until the mixture triples in volume, then fold in the flour.","timer":null},{"text":"Spread on a tray lined with baking paper and bake for 8 min.","timer":{"label":"Oven","min":8}},{"text":"Roll up the warm sponge in a damp tea towel and leave to cool.","timer":null},{"text":"Heat the cream, pour it over the chocolate and leave to cool until the ganache thickens.","timer":null},{"text":"Unroll the sponge, spread with a third of the ganache, roll up and cover with the rest.","timer":null},{"text":"Draw lines with a fork and dust with icing sugar.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Chestnut yule log","intro":"The yule log with chestnut cream, soft and melting.","minutes":60,"calories":440,"difficulty":"Difficile","imageSearch":"chestnut yule log","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"chestnut cream","plural":"chestnut cream","qty":300,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":20,"unit":"cl","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":100,"unit":"g","have":false}],"steps":[{"text":"Make the rolled sponge and bake for 8 min at 200 °C.","timer":{"label":"Oven","min":8}},{"text":"Roll it up in a damp tea towel.","timer":null},{"text":"Whip the cream and fold it into the chestnut cream.","timer":null},{"text":"Fill the sponge, roll it up and cover with melted chocolate.","timer":null}],"dessert":true,"variant":"Chestnut","change":"Filled with chestnut cream."},{"title":"Quick ice cream yule log","intro":"An easy ice cream log to make the day before.","minutes":20,"calories":380,"difficulty":"Facile","imageSearch":"ice cream yule log","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"vanilla ice cream","plural":"vanilla ice cream","qty":50,"unit":"cl","have":false},{"name":"chocolate ice cream","plural":"chocolate ice cream","qty":50,"unit":"cl","have":false},{"name":"sponge finger","plural":"sponge fingers","qty":12,"unit":"","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":100,"unit":"g","have":false}],"steps":[{"text":"Line a loaf tin with cling film.","timer":null},{"text":"Layer softened vanilla ice cream, sponge fingers and chocolate ice cream.","timer":null},{"text":"Freeze for 6 h.","timer":null},{"text":"Turn out and cover with melted chocolate just before serving.","timer":null}],"dessert":true,"variant":"Frozen","change":"With ice cream and biscuits, no baking."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gateau basque', 'Gâteau basque', array['en:basque cake', 'en:basque custard cake', 'en:cherry basque cake']::text[], 'dish', $r$[{"title":"Custard gâteau basque","intro":"A thick shortbread-style cake filled with custard and flavoured with almond.","minutes":90,"calories":420,"difficulty":"Moyen","imageSearch":"gateau basque","veg":true,"oven":true,"cold":false,"missing":"","origin":"Basque speciality","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":150,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":5,"unit":"","have":false},{"name":"ground almonds","plural":"ground almonds","qty":50,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":40,"unit":"cl","have":false},{"name":"cornflour","plural":"cornflour","qty":30,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Make the custard: heat the milk, whisk 2 eggs with 80 g of sugar and the cornflour, pour in the milk, then thicken over the heat. Leave to cool.","timer":{"label":"Cooking","min":5}},{"text":"Mix the butter and the rest of the sugar with 2 eggs, the flour, ground almonds and baking powder.","timer":null},{"text":"Chill the dough for 1 h.","timer":null},{"text":"Preheat the oven to 180 °C. Press two thirds of the dough into a tin, add the custard and cover with the rest of the dough.","timer":null},{"text":"Brush with the last egg, mark with a fork and bake for 40 min.","timer":{"label":"Oven","min":40}}],"dessert":true,"variant":"The classic","change":""},{"title":"Cherry gâteau basque","intro":"The gâteau basque filled with black cherry jam.","minutes":80,"calories":430,"difficulty":"Moyen","imageSearch":"cherry gateau basque","veg":true,"oven":true,"cold":false,"missing":"","origin":"Basque speciality","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":150,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"ground almonds","plural":"ground almonds","qty":50,"unit":"g","have":false},{"name":"black cherry jam","plural":"black cherry jam","qty":300,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Mix the butter and sugar with 2 eggs, the flour, ground almonds and baking powder. Chill for 1 h.","timer":null},{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Press two thirds of the dough into a tin and cover with the jam.","timer":null},{"text":"Top with the rest of the dough, brush with egg and bake for 40 min.","timer":{"label":"Oven","min":40}}],"dessert":true,"variant":"Cherry","change":"Filled with black cherry jam."},{"title":"Chocolate gâteau basque","intro":"The chocolate version of the gâteau basque.","minutes":90,"calories":460,"difficulty":"Moyen","imageSearch":"chocolate gateau basque","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":150,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":5,"unit":"","have":false},{"name":"ground almonds","plural":"ground almonds","qty":50,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":40,"unit":"cl","have":false},{"name":"cornflour","plural":"cornflour","qty":30,"unit":"g","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":100,"unit":"g","have":false}],"steps":[{"text":"Make a custard and stir in the chocolate at the end of cooking. Leave to cool.","timer":{"label":"Cooking","min":5}},{"text":"Make the shortbread dough and chill it for 1 h.","timer":null},{"text":"Assemble the cake: dough, custard, dough.","timer":null},{"text":"Brush with egg and bake for 40 min at 180 °C.","timer":{"label":"Oven","min":40}}],"dessert":true,"variant":"Chocolate","change":"Filled with chocolate custard."}]$r$::jsonb, 'claude')
