insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gateau aux pomme', 'Apple cake', array['en:apple cake', 'en:easy apple cake', 'en:moist apple cake', 'en:invisible apple cake']::text[], 'dish', $r$[{"title":"Moist apple cake","intro":"A simple cake full of soft apples, perfect for tea time.","minutes":60,"calories":280,"difficulty":"Facile","imageSearch":"apple cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":150,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":100,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"milk","plural":"milk","qty":5,"unit":"cl","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Whisk the eggs and sugar, then add the flour, baking powder, melted butter and milk.","timer":null},{"text":"Peel the apples, cut them into pieces and add them to the batter.","timer":null},{"text":"Pour into a buttered tin and bake for 40 min.","timer":{"label":"Oven","min":40}}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Invisible apple cake","intro":"The cake of soft apple layers, with almost no batter.","minutes":75,"calories":220,"difficulty":"Moyen","imageSearch":"apple layer cake invisible","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":6,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":80,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":15,"unit":"cl","have":false},{"name":"melted butter","plural":"melted butter","qty":30,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the eggs, sugar, flour, milk and melted butter.","timer":null},{"text":"Slice the apples very thinly and mix them into the batter.","timer":null},{"text":"Pack into a loaf tin and bake for 50 min.","timer":{"label":"Oven","min":50}}],"dessert":true,"variant":"Invisible","change":"Thin apple slices stacked with very little batter."},{"title":"Apple yoghurt cake","intro":"The apple yoghurt cake, measured with the pot.","minutes":55,"calories":260,"difficulty":"Facile","imageSearch":"apple yogurt cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":3,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"sunflower oil","plural":"sunflower oil","qty":6,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the yoghurt, sugar, eggs, flour, baking powder and oil.","timer":null},{"text":"Add the diced apples.","timer":null},{"text":"Pour into a tin and bake for 40 min.","timer":{"label":"Oven","min":40}}],"kids":true,"dessert":true,"variant":"With yoghurt","change":"Based on a yoghurt cake."}]$r$::jsonb, 'claude')
