insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:mousse au citron', 'Lemon mousse', array['en:lemon mousse', 'en:light lemon mousse', 'en:lemon dessert']::text[], 'dish', $r$[{"title":"Lemon mousse","intro":"A light, tangy lemon mousse to serve in glasses.","minutes":25,"calories":250,"difficulty":"Facile","imageSearch":"lemon mousse","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"lemon","plural":"lemons","qty":3,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":20,"unit":"cl","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Whisk the yolks, sugar, cornflour, and the juice and zest of the lemons.","timer":null},{"text":"Thicken over a low heat, stirring, then leave to cool.","timer":{"label":"Cooking","min":5}},{"text":"Whip the cream and whisk the whites until stiff.","timer":null},{"text":"Gently fold the whipped cream, then the whites, into the lemon cream.","timer":null},{"text":"Spoon into glasses and chill for 3 h.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Lime and coconut mousse","intro":"A tropical mousse with lime and coconut.","minutes":20,"calories":260,"difficulty":"Facile","imageSearch":"lime coconut mousse","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"lime","plural":"limes","qty":3,"unit":"","have":false},{"name":"coconut cream","plural":"coconut cream","qty":20,"unit":"cl","have":false},{"name":"sweetened condensed milk","plural":"sweetened condensed milk","qty":200,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":15,"unit":"cl","have":false}],"steps":[{"text":"Mix the condensed milk with the juice and zest of the limes.","timer":null},{"text":"Whip the double cream and coconut cream together, both well chilled.","timer":null},{"text":"Gently fold into the lime mixture.","timer":null},{"text":"Spoon into glasses and chill for 3 h.","timer":null}],"dessert":true,"variant":"Lime and coconut","change":"With lime and coconut cream."},{"title":"Quick lemon mousse","intro":"A quick egg-free lemon mousse.","minutes":15,"calories":220,"difficulty":"Facile","imageSearch":"eggless lemon mousse","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":300,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":20,"unit":"cl","have":false},{"name":"icing sugar","plural":"icing sugar","qty":60,"unit":"g","have":false}],"steps":[{"text":"Mix the fromage blanc, icing sugar, and the juice and zest of the lemons.","timer":null},{"text":"Whip the cream.","timer":null},{"text":"Gently fold it in.","timer":null},{"text":"Spoon into glasses and chill for 2 h.","timer":null}],"dessert":true,"variant":"Egg-free","change":"With fromage blanc and cream."}]$r$::jsonb, 'claude')
