insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:rapide', 'quick recipes', array['en:quick recipe', 'en:quick', 'en:quick and easy', 'en:fast']::text[], 'list', $r$[{"title":"Chicken fajitas","intro":"Spiced strips of chicken and peppers, rolled in tortillas.","minutes":25,"calories":520,"difficulty":"Facile","imageSearch":"chicken fajitas","veg":false,"oven":false,"cold":false,"missing":"","origin":"Tex-Mex dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"tortilla","plural":"tortillas","qty":8,"unit":"","have":false},{"name":"fajita seasoning","plural":"fajita seasoning","qty":2,"unit":"tbsp","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the chicken, peppers and onion into strips.","timer":null},{"text":"Brown the chicken in the oil with the seasoning for 6 minutes.","timer":{"label":"Pan","min":6}},{"text":"Add the vegetables and cook for 6 minutes. They should stay crunchy.","timer":{"label":"Pan","min":6}},{"text":"Warm the tortillas and fill them with the cream and the fried mix.","timer":null}],"kids":true,"makes":{"n":8,"one":"fajita","many":"fajitas"}},{"title":"Four cheese pasta","intro":"Pasta covered in a melting cream sauce with gorgonzola, mozzarella, parmesan and Emmental.","minutes":20,"calories":700,"difficulty":"Facile","imageSearch":"four cheese pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"gorgonzola","plural":"gorgonzola","qty":100,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":60,"unit":"g","have":false},{"name":"single cream","plural":"single cream","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Heat the cream over a low heat.","timer":null},{"text":"Add the gorgonzola, the diced mozzarella, the Emmental and the parmesan, and stir until everything has melted.","timer":null},{"text":"Mix with the pasta and add pepper.","timer":null}],"kids":true},{"title":"Salmon tartare","intro":"Raw salmon cut by hand, with lime, shallot and herbs.","minutes":20,"calories":300,"difficulty":"Facile","imageSearch":"salmon tartare","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"extra-fresh salmon fillet","plural":"extra-fresh salmon fillets","qty":3,"unit":"","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"chives","plural":"chives","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the salmon into small, even cubes.","timer":null},{"text":"Mix with the chopped shallot, chives, oil, the juice of the limes, salt and pepper.","timer":null},{"text":"Chill for 10 min before serving.","timer":{"label":"Chill","min":10}}]},{"title":"Homemade chicken nuggets","intro":"Crispy breaded chicken pieces, far better than shop-bought ones.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"homemade chicken nuggets","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"breadcrumbs","plural":"breadcrumbs","qty":100,"unit":"g","have":false},{"name":"cornflake","plural":"cornflakes","qty":50,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"flour","plural":"flour","qty":4,"unit":"tbsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the chicken into pieces.","timer":null},{"text":"Crush the cornflakes and mix them with the breadcrumbs and paprika.","timer":null},{"text":"Dip the chicken in the salted flour, the beaten egg and then the crumb mix.","timer":null},{"text":"Brown them in the oil for 3 min on each side.","timer":{"label":"Pan","min":6}}],"kids":true,"makes":{"n":24,"one":"nugget","many":"nuggets"}},{"title":"Warm goat's cheese salad","intro":"Grilled goat's cheese toasts on a green salad, with a honey dressing.","minutes":20,"calories":420,"difficulty":"Facile","imageSearch":"warm goat cheese salad","veg":true,"oven":true,"cold":false,"missing":"","origin":"French bistro dish","serves":4,"items":[{"name":"goat's cheese log","plural":"goat's cheese logs","qty":1,"unit":"","have":false},{"name":"baguette","plural":"baguettes","qty":1,"unit":"","have":false},{"name":"green salad","plural":"green salad","qty":1,"unit":"","have":false},{"name":"honey","plural":"honey","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"balsamic vinegar","plural":"balsamic vinegar","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the grill.","timer":null},{"text":"Cut the baguette into 8 slices and put a round of goat's cheese on each.","timer":null},{"text":"Grill for 5 minutes.","timer":{"label":"Oven","min":5}},{"text":"Mix the oil, vinegar and honey.","timer":null},{"text":"Serve the hot toasts on the dressed salad.","timer":null}]},{"title":"Chicken stir-fried noodles","intro":"Wok-fried noodles with chicken, crunchy vegetables and a soy and honey sauce.","minutes":20,"calories":520,"difficulty":"Facile","imageSearch":"chicken stir fry noodles","veg":false,"oven":false,"cold":false,"missing":"","origin":"Chinese dish","serves":4,"items":[{"name":"chinese noodle","plural":"chinese noodles","qty":300,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":1,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the noodles following the packet and rinse them in cold water.","timer":{"label":"Cooking","min":4}},{"text":"Stir-fry the chicken strips with the garlic in the oil for 5 minutes.","timer":{"label":"Wok","min":5}},{"text":"Add the julienned vegetables and cook for 4 minutes.","timer":{"label":"Wok","min":4}},{"text":"Add the noodles, soy sauce and honey, and stir-fry for 2 minutes.","timer":{"label":"Wok","min":2}}],"kids":true},{"title":"Greek salad","intro":"Tomatoes, cucumber, red onion, black olives and a nice big piece of feta.","minutes":15,"calories":320,"difficulty":"Facile","imageSearch":"greek salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"Greek salad","serves":4,"items":[{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"feta","plural":"feta","qty":200,"unit":"g","have":false},{"name":"black olive","plural":"black olives","qty":80,"unit":"g","have":false},{"name":"oregano","plural":"oregano","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the tomatoes into wedges and the cucumber into slices.","timer":null},{"text":"Thinly slice the red onion.","timer":null},{"text":"Toss the vegetables with the olives, a little salt and the olive oil.","timer":null},{"text":"Put the feta on top in chunks and sprinkle with oregano.","timer":null}]},{"title":"Courgette and parmesan pasta","intro":"Pasta with soft courgettes cooked with garlic, lemon and parmesan.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"zucchini pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":3,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":50,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Grate the courgettes or cut them into thin slices.","timer":null},{"text":"Soften them for 10 minutes with the garlic in the oil.","timer":{"label":"Pan","min":10}},{"text":"Mix with the pasta, the lemon zest and the parmesan.","timer":null}],"kids":true},{"title":"Honey and soy chicken","intro":"Chicken pieces glazed with honey, soy sauce and garlic, served with rice.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"honey soy chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"honey","plural":"honey","qty":3,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Cut the chicken into pieces and brown it for 6 min.","timer":{"label":"Pan","min":6}},{"text":"Add the honey, the soy sauce and the garlic.","timer":null},{"text":"Let it reduce for 3 min until the chicken is glazed.","timer":{"label":"Cooking","min":3}},{"text":"Sprinkle with sesame seeds.","timer":null}],"kids":true},{"title":"Pasta with homemade tomato sauce","intro":"Pasta with a proper homemade tomato sauce, with garlic and basil.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"pasta tomato sauce","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false}],"steps":[{"text":"Fry the onion and garlic in the oil.","timer":null},{"text":"Add the tomatoes, season and simmer for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Toss with the sauce, basil and parmesan.","timer":null}],"kids":true},{"title":"Avocado toast","intro":"Toasted bread, avocado mashed with lemon and a touch of chilli.","minutes":10,"calories":280,"difficulty":"Facile","imageSearch":"avocado toast","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"wholemeal bread","plural":"wholemeal bread","qty":4,"unit":"slices","have":false},{"name":"avocado","plural":"avocados","qty":2,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false},{"name":"piment d'espelette","plural":"piment d'espelette","qty":null,"unit":"","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Toast the bread.","timer":null},{"text":"Mash the avocados with the lemon juice and the salt.","timer":null},{"text":"Spread on the avocado and sprinkle with chilli and sesame seeds.","timer":null}],"makes":{"n":4,"one":"open sandwich","many":"open sandwiches"}},{"title":"Tuna and tomato pasta","intro":"Pasta in a tomato sauce with tuna, garlic and capers: the dinner for busy evenings.","minutes":20,"calories":520,"difficulty":"Facile","imageSearch":"tuna tomato pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"tuna in water","plural":"tuna in water","qty":280,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"caper","plural":"capers","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Fry the onion and the garlic in the oil.","timer":null},{"text":"Add the tomatoes and leave to simmer for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Add the flaked tuna and the capers, and mix with the pasta.","timer":null}],"kids":true},{"title":"Veal saltimbocca","intro":"Thin veal escalopes with cured ham and sage, pan-fried and deglazed with white wine.","minutes":25,"calories":380,"difficulty":"Moyen","imageSearch":"veal saltimbocca","veg":false,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"veal escalope","plural":"veal escalopes","qty":4,"unit":"","have":false},{"name":"cured ham","plural":"cured ham","qty":4,"unit":"slices","have":false},{"name":"sage","plural":"sage","qty":8,"unit":"leaves","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"flour","plural":"flour","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Flatten the escalopes and cut them in half.","timer":null},{"text":"Lay half a slice of ham and a sage leaf on each one, held with a cocktail stick.","timer":null},{"text":"Lightly flour the meat side.","timer":null},{"text":"Brown for 2 minutes on each side in the butter.","timer":{"label":"Pan","min":4}},{"text":"Deglaze with the white wine and leave to reduce for 2 minutes.","timer":null}]},{"title":"Hummus","intro":"The creamy chickpea dip, with tahini, lemon and garlic.","minutes":10,"calories":220,"difficulty":"Facile","imageSearch":"hummus","veg":true,"oven":false,"cold":true,"missing":"","origin":"Lebanese dish","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"tahini","plural":"tahini","qty":3,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"cumin","plural":"cumin","qty":0.5,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Drain the chickpeas, keeping a little of their liquid.","timer":null},{"text":"Blend them with the tahini, the lemon juice, the garlic, the cumin, the salt and 3 tbsp of the liquid, until very smooth.","timer":null},{"text":"Serve with a drizzle of oil and a pinch of paprika.","timer":null}]},{"title":"Spaghetti carbonara","intro":"The real carbonara: eggs, pecorino and guanciale, with no cream.","minutes":20,"calories":650,"difficulty":"Facile","imageSearch":"spaghetti carbonara","veg":false,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"guanciale","plural":"guanciale","qty":150,"unit":"g","have":false},{"name":"egg yolk","plural":"egg yolks","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"grated pecorino","plural":"grated pecorino","qty":60,"unit":"g","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the spaghetti in boiling salted water.","timer":{"label":"Pasta","min":10}},{"text":"Brown the guanciale slices in a pan for 5 min, with no added fat.","timer":{"label":"Pan","min":5}},{"text":"Beat the yolks, the whole egg, the pecorino and plenty of pepper.","timer":null},{"text":"Drain the pasta, keeping a little cooking water, and put it in the pan off the heat.","timer":null},{"text":"Pour in the eggs, stirring quickly, with a little cooking water to make a creamy sauce.","timer":null}]},{"title":"Creamed spinach","intro":"Spinach cooked down in cream and nutmeg, to serve as a side.","minutes":15,"calories":150,"difficulty":"Facile","imageSearch":"creamed spinach","veg":true,