insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:healthy', 'healthy recipes', array['en:healthy recipe', 'en:light', 'en:low calorie']::text[], 'list', $r$[{"title":"Prawn spring rolls","intro":"Rice paper rolled up with prawns, vermicelli, lettuce and mint, with no cooking.","minutes":30,"calories":220,"difficulty":"Moyen","imageSearch":"fresh spring rolls shrimp","veg":false,"oven":false,"cold":true,"missing":"","origin":"Vietnamese recipe","serves":4,"items":[{"name":"rice paper sheet","plural":"rice paper sheets","qty":8,"unit":"","have":false},{"name":"cooked prawn","plural":"cooked prawns","qty":16,"unit":"","have":false},{"name":"rice vermicelli","plural":"rice vermicelli","qty":80,"unit":"g","have":false},{"name":"green salad","plural":"green salad","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"fresh mint","plural":"fresh mint","qty":null,"unit":"","have":false},{"name":"hoisin sauce","plural":"hoisin sauce","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Soak the vermicelli in hot water for 5 minutes and drain them.","timer":null},{"text":"Grate the carrot and peel the prawns.","timer":null},{"text":"Dip a rice paper sheet in lukewarm water for a few seconds and lay it flat.","timer":null},{"text":"Fill with lettuce, vermicelli, carrot and mint, then 2 prawns cut in half.","timer":null},{"text":"Fold in the sides and roll up tightly. Serve with the hoisin sauce.","timer":null}],"makes":{"n":8,"one":"roll","many":"rolls"}},{"title":"Shakshuka","intro":"Poached eggs in a tomato and pepper sauce with cumin and paprika.","minutes":30,"calories":320,"difficulty":"Facile","imageSearch":"shakshuka eggs tomato","veg":true,"oven":false,"cold":false,"missing":"","origin":"North African dish","serves":4,"items":[{"name":"egg","plural":"eggs","qty":6,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false