 the spices, the lemon, the garlic and the ginger.","timer":{"label":"Rest","min":60}},{"text":"Preheat the oven to 220 °C.","timer":null},{"text":"Put the thighs on a tray and bake for 40 min.","timer":{"label":"Oven","min":40}},{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}}]},{"title":"Thai chicken and coconut soup","intro":"Tom kha kai: chicken in a coconut broth with lemongrass and lime.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"tom kha gai","veg":false,"oven":false,"cold":false,"missing":"","origin":"Thai recipe","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":1,"unit":"","have":false},{"name":"lemongrass","plural":"lemongrass","qty":2,"unit":"","have":false},{"name":"fresh ginger","plural":"fresh ginger","qty":1,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":150,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"fish sauce","plural":"fish sauce","qty":2,"unit":"tbsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Bring 50 cl of water to a simmer with the stock cube, bruised lemongrass and sliced ginger.","timer":{"label":"Cooking","min":10}},{"text":"Add the coconut milk and the chicken in thin strips, and cook for 8 min.","timer":{"label":"Cooking","min":8}},{"text":"Add the sliced mushrooms and cook for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Off the heat, add the lime juice and fish sauce.","timer":null},{"text":"Sprinkle with coriander.","timer":null}]},{"title":"Chicken wrap","intro":"A tortilla filled with chicken, salad and yoghurt sauce, rolled up tightly.","minutes":20,"calories":450,"difficulty":"Facile","imageSearch":"chicken wrap","veg":false,"oven":fa