for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add the peas and cook for 10 min with the lid on.","timer":{"label":"Cooking","min":10}},{"text":"Add salt and pepper.","timer":null}],"kids":true},{"title":"Lemon and thyme chicken","intro":"Chicken thighs roasted with lemon, garlic and thyme.","minutes":60,"calories":450,"difficulty":"Facile","imageSearch":"lemon chicken thighs","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":4,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":4,"unit":"clove","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"potato","plural":"potatoes","qty":600,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Cut the potatoes into wedges and one lemon into slices.","timer":null},{"text":"Put everything in a dish with the chicken, garlic, thyme, oil and the juice of the other lemon.","timer":null},{"text":"Bake for 45 minutes, basting from time to time.","timer":{"label":"Oven","min":45}}]},{"title":"Sautéed vegetables","intro":"Seasonal vegetables fried in a pan, still crunchy, with garlic and herbs.","minutes":25,"calories":150,"difficulty":"Facile","imageSearch":"sauteed vegetables","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":200,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},