insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:dessert', 'desserts', array['en:sweet']::text[], 'list', $r$[{"title":"Bowl cake","intro":"The breakfast cake made with oats and banana, cooked in 2 minutes in the microwave.","minutes":5,"calories":300,"difficulty":"Facile","imageSearch":"oatmeal bowl cake","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":160,"unit":"g","have":false},{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Mash the bananas in 4 bowls.","timer":null},{"text":"Add 40 g of oats, 1 egg, 5 cl of milk and a pinch of baking powder to each bowl.","timer":null},{"text":"Mix well.","timer":null},{"text":"Cook each bowl for 2 minutes in the microwave.","timer":{"label":"Microwave","min":2}}],"dessert":true},{"title":"Frangipane galette des rois","intro":"The puff pastry galette filled with frangipane, with the charm hidden inside.","minutes":60,"calories":480,"difficulty":"Moyen","imageSearch":"galette des rois","veg":true,"oven":true,"cold":false,"missing":"","origin":"French tradition","serves":4,"items":[{"name":"puff pastry","plural":"puff pastries","qty":2,"unit":"","have":false},{"name":"ground almond","plural":"ground almonds","qty":125,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Mix the ground almonds, sugar, soft butter and 2 eggs.","timer":null},{"text":"Roll out one pastry on a baking tray, spread with frangipane leaving a 2 cm border, and place the charm.","timer":null},{"text":"Cover with the second pastry and seal the edges well.","timer":null},{"text":"Brush with the last beaten egg and draw patterns with the tip of a knife.","timer":null},{"text":"Bake for 30 min.","timer":{"label":"Oven","min":30}}],"dessert":true},{"title":"Crêpes","intro":"The foolproof crêpe batter, thin and light, for a snack or Candlemas.","minutes":40,"calories":220,"difficulty":"Facile","imageSearch":"french crepes","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"melted butter","plural":"melted butter","qty":30,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Put the flour, sugar and a pinch of salt in a mixing bowl, and make a well in the middle.","timer":null},{"text":"Add the eggs, then the milk a little at a time, whisking to avoid lumps.","timer":null},{"text":"Add the melted butter and leave to rest for 30 min if you can.","timer":{"label":"Rest","min":30}},{"text":"Cook the crêpes in a hot, lightly buttered pan, 1 min on each side.","timer":null}],"kids":true,"dessert":true,"makes":{"n":15,"one":"crepe","many":"crepes"}},{"title":"Banana bread","intro":"The American loaf cake made with very ripe bananas, soft and fragrant.","minutes":70,"calories":290,"difficulty":"Facile","imageSearch":"banana bread","veg":true,"oven":true,"cold":false,"missing":"","origin":"American recipe","serves":4,"items":[{"name":"banana","plural":"bananas","qty":3,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"brown sugar","plural":"brown sugar","qty":100,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":220,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mash the bananas with a fork.","timer":null},{"text":"Mix them with the eggs, sugar and melted butter.","timer":null},{"text":"Add the flour, baking powder and cinnamon without mixing too much.","timer":null},{"text":"Pour into a buttered loaf tin and bake for 50 min.","timer":{"label":"Oven","min":50}}],"kids":true,"dessert":true},{"title":"Marble cake","intro":"The vanilla and chocolate loaf cake with pretty swirls, just like the one from tea time.","minutes":75,"calories":340,"difficulty":"Facile","imageSearch":"marble cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"melted butter","plural":"melted butter","qty":180,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":180,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"flour","plural":"flour","qty":220,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"milk","plural":"milk","qty":5,"unit":"cl","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":25,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C and butter a loaf tin.","timer":null},{"text":"Whisk the melted butter, sugar and vanilla sugar, then add the eggs one by one.","timer":null},{"text":"Add the flour, baking powder and milk.","timer":null},{"text":"Split the batter in two and add the cocoa to one half.","timer":null},{"text":"Pour the batters into the tin in alternating layers and run a fork through to marble.","timer":null},{"text":"Bake for 45 min.","timer":{"label":"Oven","min":45}}],"kids":true,"dessert":true},{"title":"Tiramisu","intro":"Coffee-soaked biscuits, a mascarpone cream and a dusting of cocoa.","minutes":30,"calories":450,"difficulty":"Facile","imageSearch":"tiramisu","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dessert","serves":4,"items":[{"name":"mascarpone","plural":"mascarpone","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"sponge finger","plural":"sponge fingers","qty":20,"unit":"","have":false},{"name":"strong coffee","plural":"strong coffee","qty":30,"unit":"cl","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Whisk the yolks with the sugar, then add the mascarpone.","timer":null},{"text":"Whisk the whites until stiff and fold them in.","timer":null},{"text":"Quickly dip the sponge fingers in the cold coffee and line a dish with them.","timer":null},{"text":"Alternate cream and sponge fingers, finishing with cream.","timer":null},{"text":"Chill for 6 h, then dust with cocoa.","timer":{"label":"Chill","min":360}}],"dessert":true},{"title":"Yogurt cake","intro":"The first cake everyone learns, soft and foolproof.","minutes":45,"calories":280,"difficulty":"Facile","imageSearch":"yogurt cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"natural yogurt","plural":"natural yogurts","qty":1,"unit":"","have":false},{"name":"flour","plural":"flour","qty":210,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":180,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sunflower oil","plural":"sunflower oil","qty":6,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Pour the yogurt into a mixing bowl.","timer":null},{"text":"Add the eggs, sugar, flour, baking powder, vanilla sugar and oil, mixing as you go.","timer":null},{"text":"Pour into a buttered tin and bake for 35 min.","timer":{"label":"Oven","min":35}}],"kids":true,"dessert":true},{"title":"Quatre-quarts pound cake","intro":"The Breton cake made with four ingredients in equal weights: eggs, sugar, flour and butter.","minutes":60,"calories":330,"difficulty":"Facile","imageSearch":"pound cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"Breton speciality","serves":4,"items":[{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":200,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":200,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C and butter a loaf tin.","timer":null},{"text":"Whisk the eggs and sugar until pale.","timer":null},{"text":"Add the flour, baking powder and a pinch of salt, then the melted butter.","timer":null},{"text":"Pour into the tin and bake for 40 min. A knife blade should come out dry.","timer":{"label":"Oven","min":40}}],"kids":true,"dessert":true},{"title":"Custard flan","intro":"The bakery flan: a firm vanilla custard on crisp pastry.","minutes":80,"calories":340,"difficulty":"Moyen","imageSearch":"french custard flan","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":1,"unit":"","have":false},{"name":"whole milk","plural":"whole milk","qty":750,"unit":"ml","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":70,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Roll the pastry out into a deep tin.","timer":null},{"text":"Heat the milk with the vanilla.","timer":null},{"text":"Whisk the eggs, sugar and cornflour, pour in the hot milk and put back on the heat, stirring until thick.","timer":{"label":"Custard","min":4}},{"text":"Pour onto the pastry and bake for 45 min.","timer":{"label":"Oven","min":45}},{"text":"Leave to cool, then chill for 4 h.","timer":{"label":"Chill","min":240}}],"kids":true,"dessert":true},{"title":"Chocolate mousse","intro":"The airy dark chocolate mousse, with just eggs and chocolate.","minutes":20,"calories":300,"difficulty":"Facile","imageSearch":"chocolate mousse","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":6,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Melt the chocolate in a bowl over simmering water and leave to cool slightly.","timer":null},{"text":"Separate the whites from the yolks, and stir the yolks into the chocolate.","timer":null},{"text":"Whisk the whites until stiff with a pinch of salt, then add the sugar.","timer":null},{"text":"Gently fold the whites into the chocolate.","timer":null},{"text":"Chill for at least 3 h.","timer":{"label":"Chill","min":180}}],"kids":true,"dessert":true},{"title":"Apple compote","intro":"Very simple homemade compote, with just apples and a little cinnamon.","minutes":30,"calories":120,"difficulty":"Facile","imageSearch":"applesauce bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":8,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":2,"unit":"tbsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Peel and core the apples and cut them into pieces.","timer":null},{"text":"Put them in a pan with 10 cl of water, the sugar and the cinnamon.","timer":null},{"text":"Cook for 20 min with the lid on, stirring from time to time.","timer":{"label":"Cooking","min":20}},{"text":"Mash with a fork or blend, depending on the texture you like.","timer":null}],"kids":true,"dessert":true},{"title":"Vanilla cupcakes","intro":"Soft vanilla cakes with a buttercream frosting.","minutes":50,"calories":350,"difficulty":"Moyen","imageSearch":"vanilla cupcakes frosting","veg":true,"oven":true,"cold":false,"missing":"","origin":"American recipe","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"icing sugar","plural":"icing sugar","qty":200,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Whisk 100 g of butter with the sugar, then add the eggs, the flour, the baking powder, the milk and the vanilla sugar.","timer":null},{"text":"Fill paper cases two-thirds full and bake for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Whisk the rest of the butter with the icing sugar to make the frosting.","timer":null},{"text":"Decorate the cooled cupcakes.","timer":null}],"kids":true,"dessert":true,"makes":{"n":12,"one":"cupcake","many":"cupcakes"}},{"title":"Apple crumble","intro":"Soft apples under a crunchy, buttery topping.","minutes":45,"calories":340,"difficulty":"Facile","imageSearch":"apple crumble","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":6,"unit":"","have":false},{"name":"flour","plural":"flour","qty":120,"unit":"g","have":false},{"name":"cold butter","plural":"cold butter","qty":100,"unit":"g","have":false},{"name":"brown sugar","plural":"brown sugar","qty":100,"unit":"g","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Cut the apples into pieces and put them in a dish with the cinnamon and 20 g of sugar.","timer":null},{"text":"Rub the flour, the rest of the sugar and the diced butter together with your fingertips.","timer":null},{"text":"Spread over the apples and bake for 30 min.","timer":{"label":"Oven","min":30}}],"kids":true,"dessert":true},{"title":"Churros","intro":"Crispy ridged Spanish fritters rolled in cinnamon sugar.","minutes":30,"calories":300,"difficulty":"Moyen","imageSearch":"churros cinnamon sugar","veg":true,"oven":false,"cold":false,"missing":"","origin":"Spanish recipe","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Bring 25 cl of water to the boil with the butter and a pinch of salt.","timer":null},{"text":"Tip in the flour all at once and stir until the dough forms a ball.","timer":null},{"text":"Put the dough in a piping bag with a star nozzle.","timer":null},{"text":"Pipe 10 cm lengths into the hot oil and fry them for 3 min.","timer":{"label":"Frying","min":3}},{"text":"Drain and roll them in the sugar mixed with the cinnamon.","timer":null}],"kids":true,"dessert":true,"makes":{"n":24,"one":"churro","many":"churros"}},{"title":"Butter shortbread","intro":"Little pure butter shortbread biscuits, cut out with a cutter.","minutes":50,"calories":90,"difficulty":"Facile","imageSearch":"butter shortbread cookies","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":125,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the soft butter, sugar, vanilla sugar and a pinch of salt.","timer":null},{"text":"Add the egg, then the flour, and shape into a ball without overworking it.","timer":null},{"text":"Chill for 30 min.","timer":{"label":"Rest","min":30}},{"text":"Preheat the oven to 180 °C. Roll out the dough and cut out the biscuits.","timer":null},{"text":"Bake for 10 min. They should stay pale.","timer":{"label":"Oven","min":10}}],"kids":true,"dessert":true,"makes":{"n":25,"one":"shortbread biscuit","many":"shortbread biscuits"}},{"title":"Waffles","intro":"Waffles that are crisp outside and soft inside.","minutes":40,"calories":300,"difficulty":"Facile","imageSearch":"waffles","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":30,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the flour, baking powder, sugars and salt.","timer":null},{"text":"Add the egg yolks, then the milk and melted butter.","timer":null},{"text":"Whisk the egg whites until stiff and fold them in gently.","timer":null},{"text":"Cook in the hot waffle iron for 3 to 4 min.","timer":{"label":"Waffle iron","min":4}}],"kids":true,"dessert":true,"makes":{"n":10,"one":"waffle","many":"waffles"}},{"title":"Cherry clafoutis","intro":"The dessert from the Limousin: cherries in a soft baked custard.","minutes":50,"calories":280,"difficulty":"Facile","imageSearch":"cherry clafoutis","veg":true,"oven":true,"cold":false,"missing":"","origin":"Limousin speciality","serves":4,"items":[{"name":"cherry","plural":"cherries","qty":500,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"flour","plural":"flour","qty":80,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":30,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Butter a dish and spread the cherries in it.","timer":null},{"text":"Whisk the eggs with the sugars, then add the flour and the milk.","timer":null},{"text":"Pour over the cherries.","timer":null},{"text":"Bake for 35 min.","timer":{"label":"Oven","min":35}}],"kids":true,"dessert":true},{"title":"New York cheesecake","intro":"The creamy cheesecake on a biscuit base, baked gently in the oven.","minutes":90,"calories":480,"difficulty":"Moyen","imageSearch":"new york cheesecake","veg":true,"oven":true,"cold":false,"missing":"","origin":"New York recipe","serves":4,"items":[{"name":"plain biscuit","plural":"plain biscuits","qty":200,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"cream cheese","plural":"cream cheese","qty":600,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 160 °C. Crush the biscuits and mix them with the melted butter.","timer":null},{"text":"Press this mixture into the bottom of a springform tin.","timer":null},{"text":"Whisk the cream cheese, sugar, cream and lemon zest, then the eggs one by one.","timer":null},{"text":"Pour over the base and bake for 1 h.","timer":{"label":"Oven","min":60}},{"text":"Leave to cool in the oven with the door ajar, then chill for at least 4 h.","timer":null}],"dessert":true},{"title":"Apple tart","intro":"Crisp pastry, homemade apple purée and golden slices of apple.","minutes":60,"calories":320,"difficulty":"Facile","imageSearch":"french apple tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":1,"unit":"","have":false},{"name":"apple","plural":"apples","qty":6,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Roll the pastry out into a tin.","timer":null},{"text":"Make a quick purée with 3 diced apples, half the sugar and a little water, for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Spread the purée over the pastry and arrange the other 3 apples on top in thin slices.","timer":null},{"text":"Sprinkle with the rest of the sugar and dot with small pieces of butter.","timer":null},{"text":"Bake for 35 min.","timer":{"label":"Oven","min":35}}],"kids":true,"dessert":true},{"title":"Almond financiers","intro":"Little almond and brown butter cakes, crisp outside and soft inside.","minutes":40,"calories":130,"difficulty":"Facile","imageSearch":"almond financiers","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"ground almond","plural":"ground almonds","qty":100,"unit":"g","have":false},{"name":"icing sugar","plural":"icing sugar","qty":150,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":50,"unit":"g","have":false},{"name":"egg white","plural":"egg whites","qty":4,"unit":"","have":false},{"name":"butter","plural":"butter","qty":120,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Heat the butter until it is golden and smells of hazelnuts.","timer":{"label":"Cooking","min":5}},{"text":"Mix the ground almonds, icing sugar and flour, then the unwhisked egg whites.","timer":null},{"text":"Add the lukewarm brown butter and fill the buttered moulds.","timer":null},{"text":"Bake for 12 min.","timer":{"label":"Oven","min":12}}],"dessert":true,"makes":{"n":12,"one":"financier","many":"financiers"}},{"title":"Walnut brownies","intro":"A dense, fudgy brownie with crunchy walnuts.","minutes":35,"calories":450,"difficulty":"Facile","imageSearch":"chocolate brownie walnuts","veg":true,"oven":true,"cold":false,"missing":"","origin":"American dish","serves":4,"items":[{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":150,"unit":"g","have":false},{"name":"brown sugar","plural":"brown sugar","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":