"timer":null},{"text":"Layer the mousse and chopped strawberries, then cover with sponge fingers.","timer":null},{"text":"Leave to set in the fridge for 6 h before turning out.","timer":null}],"dessert":true},{"title":"Carrot cake","intro":"The soft cake with carrots and spices, with its cream cheese frosting.","minutes":80,"calories":450,"difficulty":"Moyen","imageSearch":"carrot cake frosting","veg":true,"oven":true,"cold":false,"missing":"","origin":"Anglo-Saxon recipe","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"brown sugar","plural":"brown sugar","qty":150,"unit":"g","have":false},{"name":"sunflower oil","plural":"sunflower oil","qty":15,"unit":"cl","have":false},{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":2,"unit":"tsp","have":false},{"name":"cream cheese","plural":"cream cheese","qty":200,"unit":"g","have":false},{"name":"icing sugar","plural":"icing sugar","qty":60,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Finely grate the carrots.","timer":null},{"text":"Whisk the eggs, brown sugar and oil.","timer":null},{"text":"Add the flour, baking powder and cinnamon, then the carrots.","timer":null},{"text":"Pour into a buttered tin and bake for 45 min. Leave to cool.","timer":{"label":"Oven","min":45}},{"text":"Whisk the cream cheese and icing sugar, and spread this frosting over the cake.","timer":null}],"dessert":true},{"title":"Chocolate chip cookies","intro":"Cookies that are crisp at the edges and soft in the middle.","minutes":25,"calories":220,"difficulty":"Facile","imageSearch":"chocolate chip cookies","veg":true,"oven":true,"cold":false,"missing":"","origin":"American dish","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"nam