imer":{"label":"Cooking","min":5}},{"text":"Mix the butter and the rest of the sugar with 2 eggs, the flour, ground almonds and baking powder.","timer":null},{"text":"Chill the dough for 1 h.","timer":null},{"text":"Preheat the oven to 180 °C. Press two thirds of the dough into a tin, add the custard and cover with the rest of the dough.","timer":null},{"text":"Brush with the last egg, mark with a fork and bake for 40 min.","timer":{"label":"Oven","min":40}}],"dessert":true},{"title":"Glazed doughnuts","intro":"Soft ring doughnuts with a sugar glaze.","minutes":150,"calories":320,"difficulty":"Moyen","imageSearch":"glazed donuts","veg":true,"oven":false,"cold":false,"missing":"","origin":"American recipe","serves":4,"items":[{"name":"flour","plural":"flour","qty":400,"unit":"g","have":false},{"name":"yeast","plural":"yeast","qty":10,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":50,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":50,"unit":"g","have":false},{"name":"icing sugar","plural":"icing sugar","qty":200,"unit":"g","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Mix the yeast into the warm milk, then knead with the flour, the sugar, the egg and the butter.","timer":null},{"text":"Leave to rise for 1 h 30.","timer":{"label":"Rising","min":90}},{"text":"Roll out to 1 cm thick and cut out rings. Leave to rise for 30 min.","timer":{"label":"Rising","min":30}},{"text":"Fry for 1 min on each side.","timer":{"label":"Frying","min":2}},{"text":"Dip the tops in the icing sugar mixed with 3 tbsp of water.","timer":null}],"kids":true,"dessert":true,"makes":{"n":12,"one":"doughnut","many":"doughnuts"}},{"title":"Homemade brioche","intro":"A soft, stringy brioche for weekend breakfast.","minutes":180,"calories":320,"difficulty":"Moyen","imageSearch":"homemade brioche","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":500,"unit":"g","have":false},{"name":"baker's yeast","plural":"baker's yeast","qty":10,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":150,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Dissolve the yeast in the lukewarm milk.","timer":null},{"text":"Mix the flour, sugar, 1 tsp of salt, 3 eggs and the milk, then knead for 10 min.","timer":{"label":"Kneading","min":10}},{"text":"Add the soft butter in pieces and keep kneading until the dough is smooth.","timer":null},{"text":"Leave to rise for 1 h 30 under a tea towel.","timer":{"label":"Rise","min":90}},{"text":"Shape 6 balls into a loaf tin and leave to rise for another 45 min.","timer":{"label":"Rise","min":45}},{"text":"Preheat the oven to 180 °C, brush with the last beaten egg and bake for 30 min.","timer":{"label":"Oven","min":30}}],"kids":true,"dessert":true},{"title":"Tarte tatin","intro":"The upside-down tart: caramelised apples under crisp pastry.","minutes":70,"calories":380,"difficulty":"Moyen","imageSearch":"tarte tatin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":1,"unit":"","have":false},{"name":"apple","plural":"apples","qty":7,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 190 °C.","timer":null},{"text":"Make an amber caramel with the sugar in a pan that can go on the hob, then add the butter.","timer":{"label":"Caramel","min":6}},{"text":"Pack the apple wedges tightly into the caramel and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Cover with the pastry, tucking in the edges, and bake for 30 min.","timer":{"label":"Oven","min":30}},{"text":"Leave to cool for 10 min, then turn out onto a plate.","timer":{"label":"Rest","min":10}}],"dessert":true}]$r$::jsonb, 'claude')
