il","qty":5,"unit":"tbsp","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false}],"steps":[{"text":"Cut the leeks into chunks and boil them for 15 min in salted water.","timer":{"label":"Cooking","min":15}},{"text":"Boil the eggs for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Make the vinaigrette with the mustard, the vinegar, the oil and the chopped shallot.","timer":null},{"text":"Drain the leeks, pour over the vinaigrette and grate the eggs on top.","timer":null}]},{"title":"Tuna rillettes","intro":"Tuna mashed with soft cheese and lemon, to spread on toast with drinks.","minutes":10,"calories":180,"difficulty":"Facile","imageSearch":"tuna rillettes","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"tuna in brine","plural":"tuna in brine","qty":280,"unit":"g","have":false},{"name":"soft cheese","plural":"soft cheese","qty":150,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"chive","plural":"chives","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Drain the tuna.","timer":null},{"text":"Mash it with a fork and the soft cheese.","timer":null},{"text":"Add the lemon juice, the chopped chives and some pepper.","timer":null},{"text":"Keep it cold and serve with toasted bread.","timer":null}]},{"title":"Stuffed mushrooms","intro":"Big mushrooms stuffed with garlic, parsley and soft cheese, then baked until golden.","minutes":30,"calories":180,"difficulty":"Facile","imageSearch":"stuffed mushrooms","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"button mushroom","plural":"button mushrooms","qty":12,"unit":"","have":false},{"name":"garlic and herb soft cheese","plural":"garlic and herb soft cheese","qty":150,"unit":"g","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":2,"unit":"tbsp","have":false},{"name":"par