"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the tomatoes into wedges and the cucumber into slices.","timer":null},{"text":"Thinly slice the red onion.","timer":null},{"text":"Toss the vegetables with the olives, a little salt and the olive oil.","timer":null},{"text":"Put the feta on top in chunks and sprinkle with oregano.","timer":null}]},{"title":"Lentil salad","intro":"Warm green lentils with shallot, parsley and a mustard dressing.","minutes":35,"calories":340,"difficulty":"Facile","imageSearch":"lentil salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"green lentil","plural":"green lentils","qty":250,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false},{"name":"red wine vinegar","plural":"red wine vinegar","qty":2,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the lentils for 25 minutes in water with the diced carrot.","timer":{"label":"Cooking","min":25}},{"text":"Make the dressing with the mustard, vinegar, oil, salt and pepper.","timer":null},{"text":"Drain the lentils and toss them while warm with the sliced shallots, parsley and dressing.","timer":null}]},{"title":"Beef empanadas","intro":"Golden Argentinian turnovers filled with beef, onions and paprika.","minutes":60,"calories":380,"difficulty":"Moyen","imageSearch":"beef empanadas","veg":false,"oven":true,"cold":false,"missing":"","origin":"Argentinian recipe","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":2,"unit":"","have":false},{"name":"minced beef","plural":"minced beef","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":2,"unit":"tsp","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false}],"steps":[{"text":"Fry the diced onions and pepper, then add the beef and spices and cook for 8 min.","timer":{"label":"Pan","min":8}},{"text":"Hard-boil an egg for 10 min, chop it and add it to the filling.","timer":{"label":"Cooking","min":10}},{"text":"Preheat the oven to 200 °C. Cut 12 cm circles from the pastry.","timer":null},{"text":"Spoon the filling onto half of each circle, fold over and press the edges closed with a fork.","timer":null},{"text":"Brush with the second beaten egg and bake for 20 min.","timer":{"label":"Oven","min":20}}],"makes":{"n":12,"one":"empanada","many":"empanadas"}}]$r$::jsonb, 'claude')
