insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:plat', 'main dishes', array['en:main dishe', 'en:main']::text[], 'list', $r$[{"title":"Creamed spinach","intro":"Spinach cooked down in cream and nutmeg, to serve as a side.","minutes":15,"calories":150,"difficulty":"Facile","imageSearch":"creamed spinach","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"baby spinach","plural":"baby spinach","qty":600,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":15,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false}],"steps":[{"text":"Melt the chopped garlic in the butter.","timer":null},{"text":"Add the spinach a handful at a time and let it wilt for 3 min.","timer":{"label":"Pan","min":3}},{"text":"Add the cream and the nutmeg.","timer":null},{"text":"Let it reduce for 3 min, then add salt and pepper.","timer":{"label":"Cooking","min":3}}],"kids":true},{"title":"Peas and carrots","intro":"Tender peas and carrots cooked with onion and butter.","minutes":30,"calories":150,"difficulty":"Facile","imageSearch":"peas and carrots","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"frozen pea","plural":"frozen peas","qty":500,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Soften the sliced onion in the butter.","timer":null},{"text":"Add the sliced carrots, the sugar and 15 cl of water, and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add the peas and cook for 10 min with the lid on.","timer":{"label":"Cooking","min":10}},{"text":"Add salt and pepper.","timer":null}],"kids":true},{"title":"Croque-monsieur","intro":"The golden, melting croque, with ham, emmental and a touch of béchamel.","minutes":20,"calories":450,"difficulty":"Facile","imageSearch":"croque monsieur ham cheese","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sandwich bread","plural":"sandwich breads","qty":8,"unit":"slices","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"grated emmental","plural":"grated emmental","qty":120,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":15,"unit":"cl","have":false},{"name":"plain flour","plural":"plain flour","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Make a small béchamel: melt 15 g of butter, add the flour, then the milk, whisking for 3 min.","timer":{"label":"Béchamel","min":3}},{"text":"Preheat the oven to 220 °C. Lightly butter the outside of the bread slices.","timer":null},{"text":"Top 4 slices with béchamel, ham and emmental, then cover with the other slices.","timer":null},{"text":"Add a little béchamel and emmental on top.","timer":null},{"text":"Bake for 10 min, until nicely golden.","timer":{"label":"Oven","min":10}}],"kids":true,"makes":{"n":4,"one":"toastie","many":"toasties"}},{"title":"Ham and olive savoury cake","intro":"The savoury loaf cake for nibbles and picnics, with ham and olives.","minutes":60,"calories":320,"difficulty":"Facile","imageSearch":"savory ham olive loaf cake","veg":false,"oven":true,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"olive oil","plural":"olive oil","qty":10,"unit":"cl","have":false},{"name":"diced ham","plural":"diced ham","qty":150,"unit":"g","have":false},{"name":"green olive","plural":"green olives","qty":100,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the flour, baking powder, eggs, milk and oil.","timer":null},{"text":"Add the ham, the chopped olives, the emmental, salt and pepper.","timer":null},{"text":"Pour into a loaf tin and bake for 45 min.","timer":{"label":"Oven","min":45}}],"kids":true},{"title":"Sausage and mash","intro":"Browned Toulouse sausages with homemade mash and onion gravy.","minutes":40,"calories":720,"difficulty":"Facile","imageSearch":"sausage mash onion gravy","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"toulouse sausage","plural":"toulouse sausages","qty":4,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"beef stock cube","plural":"beef stock cubes","qty":1,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes for 20 min in salted water.","timer":{"label":"Cooking","min":20}},{"text":"Brown the sausages for 15 min in a pan, turning them.","timer":{"label":"Pan","min":15}},{"text":"Take them out and soften the sliced onions in the pan, then add the stock cube and 20 cl of water, and let it reduce.","timer":{"label":"Cooking","min":8}},{"text":"Mash the potatoes with the milk and the butter.","timer":null},{"text":"Serve the sausages on the mash, covered with gravy.","timer":null}],"kids":true},{"title":"Chicken noodle soup","intro":"The comforting chicken broth with carrots and vermicelli, for cold-sniffle evenings.","minutes":50,"calories":280,"difficulty":"Facile","imageSearch":"chicken noodle soup","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vermicelli","plural":"vermicelli","qty":80,"unit":"g","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Put the chicken, onion and bouquet garni in 1.5 litres of salted water and simmer for 30 min.","timer":{"label":"Cooking","min":30}},{"text":"Take out the chicken and shred it.","timer":null},{"text":"Add the sliced carrots and leek, and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add the vermicelli and chicken, and cook for 4 min.","timer":{"label":"Cooking","min":4}},{"text":"Sprinkle with parsley.","timer":null}],"kids":true},{"title":"Beef Stroganoff","intro":"Strips of beef seared in a creamy mushroom and paprika sauce.","minutes":30,"calories":560,"difficulty":"Facile","imageSearch":"beef stroganoff","veg":false,"oven":false,"cold":false,"missing":"","origin":"Russian recipe","serves":4,"items":[{"name":"fondue beef","plural":"fondue beef","qty":600,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"crème fraîche","pl