Cover with the rinsed rice and 55 cl of water, without stirring.","timer":null},{"text":"Cover and cook for 20 minutes over a low heat.","timer":{"label":"Cooking","min":20}},{"text":"Sprinkle with the reserved onions and coriander.","timer":null}]},{"title":"Caesar salad","intro":"Crunchy romaine, golden chicken, croutons and a Parmesan Caesar dressing.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"caesar salad chicken","veg":false,"oven":false,"cold":true,"missing":"","origin":"American dish","serves":4,"items":[{"name":"romaine lettuce","plural":"romaine lettuces","qty":1,"unit":"","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"sliced white bread","plural":"sliced white bread","qty":3,"unit":"slices","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":40,"unit":"g","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":3,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken in 1 tbsp of oil for 10 minutes, then slice it.","timer":{"label":"Pan","min":10}},{"text":"Cut the bread into cubes and brown them for 3 minutes in the rest of the oil with the garlic.","timer":{"label":"Pan","min":3}},{"text":"Mix the mayonnaise, the juice of the lemon, half the Parmesan, salt and pepper.","timer":null},{"text":"Toss the lettuce with the dressing, then add the chicken, croutons and the rest of the Parmesan.","timer":null}],"kids":true},{"title":"Baked salmon fillets","intro":"Tender salmon fillets baked in the oven with lemon, dill and a drizzle of olive oil.","minutes":25,"calories":420,"difficulty":"Facile","