bs, salt and pepper.","timer":null},{"text":"Bake for 35 min, stirring halfway through.","timer":{"label":"Oven","min":35}}]},{"title":"Caprese salad","intro":"Tomatoes, mozzarella and basil with a drizzle of olive oil: Italy in 10 minutes.","minutes":10,"calories":280,"difficulty":"Facile","imageSearch":"caprese salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"Italian salad","serves":4,"items":[{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"mozzarella","plural":"mozzarella","qty":2,"unit":"","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Slice the tomatoes and the mozzarella.","timer":null},{"text":"Arrange them in alternating layers on a plate.","timer":null},{"text":"Scatter over the basil leaves.","timer":null},{"text":"Drizzle with olive oil and season with salt and pepper just before serving.","timer":null}]},{"title":"Eggs mimosa","intro":"The timeless starter: hard-boiled eggs filled with a mayonnaise stuffing.","minutes":25,"calories":220,"difficulty":"Facile","imageSearch":"deviled eggs mimosa","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":8,"unit":"","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":4,"unit":"tbsp","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false},{"name":"chive","plural":"chives","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the eggs for 10 min in boiling water, then cool them.","timer":{"label":"Eggs","min":10}},{"text":"Peel them and cut in half. Take out the yolks.","timer":null},{"text":"Mash the yolks with the mayonnaise, mustard, salt and pepper.","timer":null},{"text":"Fill the whites and sprinkle with chives.","timer":null}],"kids":true,"makes":{"n":16,"one":"devilled egg","many":"devilled eggs"}},{"title":"Creamy parmesan polenta","intro":"A smooth polenta with parmesan and butter, to serve with a meat in sauce.","minutes":15,"calories":320,"difficulty":"Facile","imageSearch":"creamy polenta","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"instant polenta","plural":"instant polenta","qty":250,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"parmesan","plural":"parmesan","qty":60,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Bring the milk to the boil with 50 cl of salted water.","timer":null},{"text":"Pour in the polenta in a thin stream, whisking.","timer":null},{"text":"Cook for 5 minutes, stirring.","timer":{"label":"Cooking","min":5}},{"text":"Stir in the parmesan and the butter off the heat.","timer":null}],"kids":true},{"title":"Baked eggs with cream","intro":"Eggs baked in ramekins, with cream and chives.","minutes":20,"calories":200,"difficulty":"Facile","imageSearch":"baked eggs ramekin cream","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":8,"unit":"tbsp","have":false},{"name":"chive","plural":"chives","qty":null,"unit":"","have":false},{"name":"butter","plural":"butter","qty":10,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Butter 4 ramekins.","timer":null},{"text":