":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and the pepper strips in the oil for 8 minutes.","timer":{"label":"Pan","min":8}},{"text":"Add the garlic, spices and tomatoes, season with salt and simmer for 10 minutes.","timer":{"label":"Simmer","min":10}},{"text":"Make small wells and crack an egg into each one.","timer":null},{"text":"Cover and cook for 6 minutes, until the whites are set.","timer":{"label":"Cooking","min":6}},{"text":"Sprinkle with coriander and serve with bread.","timer":null}]},{"title":"Potato salad","intro":"Warm potatoes, a shallot dressing and lots of chives.","minutes":30,"calories":280,"difficulty":"Facile","imageSearch":"potato salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"chives","plural":"chives","qty":null,"unit":"","have":false},{"name":"oil","plural":"oil","qty":4,"unit":"tbsp","have":false},{"name":"vinegar","plural":"vinegar","qty":2,"unit":"tbsp","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Boil the potatoes in salted water for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Peel them while still warm and cut into slices.","timer":null},{"text":"Mix the mustard, vinegar, oil and chopped shallot.","timer":null},{"text":"Pour over the potatoes while still warm and sprinkle with chives.","timer":null}]},{"title":"Comté go