insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poulet', 'chicken', array['en:chicken']::text[], 'list', $r$[{"title":"Chicken mafé","intro":"Chicken simmered in a smooth peanut and tomato sauce.","minutes":70,"calories":620,"difficulty":"Moyen","imageSearch":"chicken peanut stew mafe","veg":false,"oven":false,"cold":false,"missing":"","origin":"West African dish","serves":4,"items":[{"name":"chicken leg","plural":"chicken legs","qty":4,"unit":"","have":false},{"name":"peanut butter","plural":"peanut butter","qty":4,"unit":"tbsp","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"tomato purée","plural":"tomato purée","qty":1,"unit":"tbsp","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"sweet potato","plural":"sweet potatoes","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken in the oil with the onions.","timer":null},{"text":"Add the garlic, tomatoes, tomato purée and 50 cl of water.","timer":null},{"text":"Mix the peanut butter with a little of the sauce and stir it in.","timer":null},{"text":"Add the carrots and sweet potato in chunks, and simmer for 45 minutes. Serve with rice.","timer":{"label":"Simmer","min":45}}]},{"title":"Chicken wrap","intro":"A tortilla filled with chicken, salad and yoghurt sauce, rolled up tightly.","minutes":20,"calories":450,"difficulty":"Facile","imageSearch":"chicken wrap","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"flour tortilla","plural":"flour tortillas","qty":4,"unit":"","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"u